
(() => {
'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = s => String(s ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const paths={book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4V4Zm9 3a3 3 0 0 1 3-3h4v15h-4a4 4 0 0 0-3 2',side:'M4 4h16v16H4zM10 4v16',sun:'M15.5 12a3.5 3.5 0 1 1-7 0 3.5 3.5 0 0 1 7 0M12 2.5v2M12 19.5v2M4.6 4.6 6 6M18 18l1.4 1.4M2.5 12h2M19.5 12h2M4.6 19.4 6 18M18 6l1.4-1.4',moon:'M20 15.2A8.2 8.2 0 0 1 8.8 4a8.4 8.4 0 1 0 11.2 11.2Z',open:'M3 7h7l2 3h9l-3 10H3V7Zm0 0V4h7l2 3h7v3',back:'m14 5-7 7 7 7M7 12h13',chevron:'m9 5 7 7-7 7',close:'m6 6 12 12M6 18 18 6',more:'M5 12h.1m6.9 0h.1m6.9 0h.1',bookmark:'M6 3h12v18l-6-4-6 4V3Z',search:'M16 16l5 5M18 10a8 8 0 1 1-16 0 8 8 0 0 1 16 0',minus:'M5 12h14',plus:'M5 12h14M12 5v14',rotate:'M20 7V3l-4 4M20 7a8 8 0 1 0 0 10',undo:'M8 5 3 10l5 5M3 10h11a6 6 0 0 1 6 6',check:'m5 12 4 4L19 6',settings:'M4 6h16M4 12h16M4 18h16M8 3v6m8 0v6M10 15v6',arrow:'M5 12h14m-6-6 6 6-6 6',download:'M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4',spark:'m12 3 2.5 6.5L21 12l-6.5 2.5L12 21l-2.5-6.5L3 12l6.5-2.5L12 3Z',copy:'M8 8h12v13H8zM16 8V3H3v13h5',trash:'M4 6h16M9 6V3h6v3M6 6l1 15h10l1-15M10 10v7m4-7v7'};
const icon = name => `<svg class="od-icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[name]||paths.book}"/></svg>`;
const btn=(label,action,cls='',ico='',extra='')=>`<button type="button" class="${cls}" data-action="${action}" ${extra}>${ico?icon(ico):''}${label}</button>`;
const ib=(label,action,ico,extra='')=>btn('',action,'iconbtn',ico,`aria-label="${label}" title="${label}" ${extra}`);
const chapters=[
{title:'阅读，是建立连接',paras:['一本书的价值，不只存在于最后一页。读者在段落间停留，把一个观点与另一个经验相连，也把作者的问题带回自己的生活。','理解不是把所有句子记下来，而是辨认哪些内容值得留下。批注让这份判断可见：一句摘录、一段疑问，或是一个尚未完成的想法。','阅读工具应当保护这种专注。当工具退到背景里，读者才能把注意力交给文字。']},
{title:'从摘录到理解',paras:['摘录是一种选择。我们从连续的文字中，辨认出一个值得再次回看的片段。这种选择本身，就已经是理解的开始。','单独保存一句话，往往不足以保留它的含义。它来自哪个问题，回应了什么论证，又受到哪些条件的限制，都需要上下文。','当摘录与原文保持连接，笔记便有了可以返回的坐标。我们既能顺着一句话回到整章，也能从新的问题重新审视旧的判断。','跨文档阅读，让不同作者的解释进入同一个视野。相同的词语未必指向相同的概念；看似矛盾的观点，也可能建立在不同的前提上。','因此，研究的下一步不是收集更多片段，而是整理它们之间的关系：哪些是证据，哪些是推论，哪些仍然只是一个待核实的猜想。']},
{title:'让证据保留来处',paras:['引用的力量来自它可以被核实。读者应当能够找到原始段落，检查语境，并形成自己的判断。','当文件发生移动，或排版改变了页码，稳定的位置仍然重要。章节和原文片段共同提供寻找线索。','好的研究笔记区分作者的原话与自己的解释。让证据保留来处，也让结论保留修改的余地。']}
];
const docs=[{id:'epub',name:'阅读与理解',ext:'EPUB',detail:'Booklight 原型示例 · 自编文本'},{id:'pdf',name:'光学实验记录',ext:'PDF',detail:'Booklight 原型示例 · 自编版式'}];
const corpus=[...chapters.flatMap((c,ci)=>c.paras.map((text,pi)=>({id:`e${ci}-${pi}`,doc:'epub',text,chapter:ci,para:pi,loc:`第 ${ci+1} 章 · 段落 ${pi+1}`}))),{id:'p3',doc:'pdf',text:'实验记录需要保留测量条件与原始数据。比较两次测量时，应先核实采样率、光路和环境条件是否一致，再分析差异。',page:3,loc:'第 3 页'}];
let storage=true;
let saved={};try{saved=JSON.parse(localStorage.getItem('booklight-v2')||'{}')}catch{storage=false}
const THEME_KEY='booklight.prototype.theme';
const themeMedia=matchMedia('(prefers-color-scheme: dark)');
function preferredTheme(){try{const v=localStorage.getItem(THEME_KEY);if(v==='light'||v==='dark')return v;}catch{}return themeMedia.matches?'dark':'light'}
function saveTheme(){try{localStorage.setItem(THEME_KEY,S.theme)}catch{}}
const S={screen:document.body.dataset.screen||'welcome',theme:preferredTheme(),chapter:saved.chapter??1,notes:saved.notes||[{id:'seed',text:chapters[1].paras[2],note:'摘录要能回到上下文。',chapter:1,para:2,color:'yellow'}],deck:saved.deck||[],memos:saved.memos||{},settings:saved.settings||{font:18,line:1.9,width:640,readTheme:'follow',provider:'未配置',url:'',model:'',language:'zh'},side:matchMedia('(min-width:768px)').matches,sideTab:'toc',deckOpen:true,selection:'',selectionPara:0,save:'saved',pdfPage:3,pdfPages:[1,2,3,4,5,6],rotations:{},pdfMode:'double',zoom:100,fit:true,pdfDirty:false,undo:[],query:'摘录',match:'any',scope:['epub','pdf'],searched:true,chat:[],operation:'对话',aiScope:'当前章',busy:false,bookmark:false,returnTo:null,scroll:0,file:null};
let timer,toastTimer,selectionRange=null,dialogBack=null;
function persist(){try{localStorage.setItem('booklight-v2',JSON.stringify({theme:S.theme,chapter:S.chapter,notes:S.notes,deck:S.deck,memos:S.memos,settings:S.settings}));return true}catch{storage=false;return false}}
function announce(t){$('#live').textContent=t;const n=$('#toast');n.textContent=t;n.hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.hidden=true,4000)}
function download(name,text,type='application/json'){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function applyTheme(){document.documentElement.classList.toggle('dark',S.theme==='dark');document.documentElement.style.setProperty('--body-size',S.settings.font+'px');document.documentElement.style.setProperty('--reader-line',S.settings.line);document.documentElement.style.setProperty('--measure',S.settings.width+'px')}
function readerStyle(){const m=S.settings.readTheme;if(m==='paper')return '--read-bg:#F7F4EF;--read-ink:#292524';if(m==='sepia')return '--read-bg:#EFE6D5;--read-ink:#292524';if(m==='night')return '--read-bg:#171412;--read-ink:#e3ded8';return ''}
// Theme toggle: the icon shows the theme you are in; the name is the theme a click switches to.
const themeName=()=>S.theme==='dark'?'切换浅色主题':'切换深色主题';
function themeToggle(){return ib(themeName(),'theme',S.theme==='dark'?'moon':'sun')}
// Keep the toggle in step when the theme changes from the settings select (no re-render, focus stays on the select).
function syncThemeToggle(){const b=$('[data-action="theme"]');if(!b)return;b.setAttribute('aria-label',themeName());b.title=themeName();b.innerHTML=icon(S.theme==='dark'?'moon':'sun')}
function header(){return `<header class="topbar"><button class="brand" data-action="nav" data-to="welcome" aria-label="Booklight 首页"><span class="brand-dot"></span>Booklight</button><nav class="topnav" aria-label="主导航">${btn('阅读','nav', ['reading','pdf','ai'].includes(S.screen)?'active':'','',`data-to="${S.file?'pdf':'reading'}" ${['reading','pdf','ai'].includes(S.screen)?'aria-current="page"':''}`)}${btn('研究','nav',S.screen==='research'?'active':'','',`data-to="research" ${S.screen==='research'?'aria-current="page"':''}`)}</nav><div class="sp"></div><div class="global-actions">${btn('<span class="open-label">打开文档</span>','open','','open','aria-label="打开文档"')}${taskBanner()}${themeToggle()}${ib('设置','nav','settings','data-to="settings"')}</div></header>`}
function status(text,extra=''){return `<footer class="statusbar"><span>${text}</span><span class="sp"></span>${extra}</footer>`}
function docbar(pdf=false,ai=false){let title=pdf?(S.file?S.file.name:'光学实验记录'):docs[0].name;return `<div class="docbar">${ib('显示或隐藏侧栏','sidebar','side',`aria-expanded="${S.side}"`)}<div class="doc-info od-field od-fill"><span class="docname od-truncate">${esc(title)}</span><span class="docsub">${pdf?'PDF':`EPUB · 第 ${S.chapter+1} / 3 章`}${S.file?' · 本机文件':' · 自编示例'}</span></div>${S.returnTo?btn('返回检索结果','return-results','text back-result','back'):''}<div class="toolbar">${!pdf?ib(S.bookmark?'移除本章书签':'书签本章','bookmark','bookmark',`aria-pressed="${S.bookmark}"`):''}${pdf?btn('页面','pdf-menu','','more',S.file?'disabled title="真实文件仅供原生 PDF 查看，编辑为示例操作"':''):btn('排版','typeset','','settings')}${!ai?btn('AI 助手',pdf?'pdf-ai':'nav','text','spark',pdf?'':'data-to="ai"'):btn('收起助手','nav','text','close','data-to="reading"')}</div></div>`}
function welcome(){return `<main class="welcome"><section><div class="eyebrow">留住阅读中的发现</div><h1>让每一次阅读，<br>都有迹可循。</h1><p class="intro">打开文档，安静阅读。<br>把值得留下的文字，连同它的来处一起保存。</p>${btn('打开文档','open','primary','open')}<p class="tiny muted">也可以将 PDF 拖入窗口</p><p class="privacy-note">文件留在本机。原型中的 AI 使用本地示例回答，不连接外部服务。</p></section><section><h2>继续阅读</h2>${docs.map((d,i)=>`<div class="recent"><span class="type">${d.ext}</span><button data-action="nav" data-to="${d.id==='pdf'?'pdf':'reading'}"><span class="od-field"><strong>${d.name}</strong><small>${d.detail}</small><small class="linklike">${i?'第 '+S.pdfPage+' 页':'第 '+(S.chapter+1)+' 章 · '+chapters[S.chapter].title}</small></span></button>${icon('chevron')}</div>`).join('')}<p class="tiny muted">以上为可操作的示例文档；PDF 可通过“打开文档”在本机查看。</p><div style="margin-top:32px">${btn('前往研究工作台','nav','text','arrow','data-to="research"')}</div></section></main>`}
function saveStatus(){if(S.save==='saving')return '正在保存批注…';if(S.save==='error')return '批注保留在本次会话，尚未持久保存';return storage?'<span class="save-dot"></span>批注已保存在此浏览器':'批注仅保留在本次会话'}
function sideReading(){return `<aside class="side ${S.side?'mobile-open':''}" ${S.side?'':'hidden'}><div class="side-tabs">${btn('目录','side-tab',S.sideTab==='toc'?'active':'','','data-tab="toc"')}${btn('批注 '+S.notes.length,'side-tab',S.sideTab==='notes'?'active':'','','data-tab="notes"')}</div><div class="side-list">${S.sideTab==='toc'?chapters.map((c,i)=>`<button class="side-item ${i===S.chapter?'active':''}" data-action="chapter" data-n="${i}" ${i===S.chapter?'aria-current="true"':''}><small>第 ${i+1} 章</small><span>${c.title}</span></button>`).join(''):S.notes.length?S.notes.map(n=>`<div class="side-item"><button class="text" data-action="note-jump" data-id="${n.id}" style="text-align:left;justify-content:flex-start;padding:0"><span class="od-field"><small>第 ${n.chapter+1} 章 · ${n.color==='yellow'?'黄色':n.color==='blue'?'蓝色':'绿色'}高亮</small><span class="od-clamp-3">${esc(n.text)}</span></span></button>${n.note?`<small>${esc(n.note)}</small>`:''}<div class="od-row">${btn('编辑','note-edit','text','','data-id="'+n.id+'"')}${ib('删除批注','note-delete','trash','data-id="'+n.id+'"')}</div></div>`).join(''):'<p class="tiny muted">选中正文，留下第一条批注。</p>'}</div><div class="side-foot">${saveStatus()}<br>${btn('导出批注','export-notes','text','download')}</div></aside>`}
function prose(){const c=chapters[S.chapter];return `<article class="prose" id="prose"><div class="chapter-no">READING NOTES / 0${S.chapter+1}</div><h1>${c.title}</h1>${c.paras.map((t,i)=>{let html=esc(t);S.notes.filter(n=>n.chapter===S.chapter&&n.para===i).forEach(n=>{if(html.includes(esc(n.text)))html=html.replace(esc(n.text),`<mark class="${n.color==='yellow'?'':n.color}">${esc(n.text)}</mark>`)});return `<p data-para="${i}" id="para-${i}">${html}</p>`}).join('')}<blockquote>“让笔记有来处，让理解有余地。”</blockquote><p class="tiny muted" style="font-family:system-ui">Booklight 自编示例文本 · 非真实出版物摘录</p></article>`}
function reading(ai=false){return `<div class="view">${docbar(false,ai)}<div class="workspace ${S.side?'side-visible':''} ${ai?'ai-layout':''}">${!ai?sideReading():''}<main class="view"><div class="selection-tools" id="selectionTools" ${S.selection?'':'hidden'}><span class="muted tiny">已选 ${Array.from(S.selection).length} 字符</span>${btn('高亮','highlight','','','data-color="yellow"')}${btn('蓝色','highlight','','','data-color="blue"')}${btn('绿色','highlight','','','data-color="green"')}${btn('写笔记','note-new')}${btn('复制','copy-selection','','copy')}${btn('询问 AI','selection-ai','text','spark')}${ib('清除选区','clear-selection','close')}</div><div class="reader-scroll reader-paper" id="readerScroll" style="${readerStyle()}">${prose()}</div><div class="docbar" style="justify-content:space-between;border-top:1px solid var(--line);border-bottom:0">${btn('上一章','chapter-prev','text','back',S.chapter===0?'disabled':'')}<span class="tiny muted">第 ${S.chapter+1} / 3 章</span>${btn('下一章','chapter-next','text','arrow',S.chapter===2?'disabled':'')}</div>${status(saveStatus(),'<span>选中文字以高亮或批注</span>')}</main>${ai?aiPanel():''}</div></div>`}
const diagram=`<svg class="doc-diagram" viewBox="0 0 440 180" role="img" aria-label="示例光路图：光源经分束器分为参考光与测量光，在探测器汇合"><g fill="none" stroke="var(--mute)" stroke-width="1.5"><path d="M50 100H205V40H330V100H390M205 100v55h125v-55"/><rect x="10" y="82" width="65" height="36" rx="3"/><rect x="180" y="80" width="50" height="40" rx="3"/><rect x="300" y="24" width="60" height="32" rx="3"/><rect x="300" y="139" width="60" height="32" rx="3"/><rect x="370" y="82" width="65" height="36" rx="3"/></g><g font-size="12" fill="var(--ink)" text-anchor="middle" font-family="system-ui"><text x="42" y="105">光源</text><text x="205" y="105">分束器</text><text x="330" y="45">参考臂</text><text x="330" y="160">测量臂</text><text x="402" y="105">探测器</text></g></svg>`;
function pdfPage(page){const rotated=(S.rotations[page]||0)%180!==0;return `<article class="pdf-sheet ${page===S.pdfPage?'selected':''} ${rotated?'landscape':''}" style="--page-width:${S.fit?'min(100%,620px)':Math.min(1000,620*S.zoom/100)+'px'}" aria-label="示例第 ${page} 页${rotated?'，横向':''}"><div class="tiny muted" style="letter-spacing:1px">OPTICAL LAB / 实验记录</div><h2>${page===3?'2.3 共路干涉布局':page===4?'2.4 测量与误差分析':'实验记录 · '+page}</h2><p>实验的可重复性依赖于清晰的记录。以下版式用于展示图表、正文与页面比例，不作为工程参数或操作依据。</p><h3>光路与测量条件</h3><p>参考光与测量光经过不同路径后重新汇合。记录光路条件、环境变化与采样方式，有助于解释观测结果。</p>${diagram}<p class="tiny muted" style="text-align:center">图 2-${page}　光路结构示意（自编）</p><h3>记录项目</h3><table><thead><tr><th>项目</th><th>应记录的内容</th></tr></thead><tbody><tr><td>环境条件</td><td>温度、振动及观测时间</td></tr><tr><td>采样方式</td><td>采样率、窗口与设备配置</td></tr><tr><td>对照记录</td><td>原始数据与处理步骤</td></tr></tbody></table><p style="margin-top:20px">${corpus.find(x=>x.id==='p3').text}</p><div class="folio"><span>Booklight 自编版式示例</span><span>${page}</span></div></article>`}
function pdf(){let idx=S.pdfPages.indexOf(S.pdfPage);if(idx<0){S.pdfPage=S.pdfPages[0];idx=0}const shown=S.pdfMode==='double'?S.pdfPages.slice(idx,idx+2):[S.pdfPage];return `<div class="view">${docbar(true)}<div class="workspace ${S.side?'side-visible':''}"><aside class="side ${S.side?'mobile-open':''}" ${S.side?'':'hidden'}><div class="side-head"><h2>页面</h2><span class="tiny muted">${S.file?'本机文件':S.pdfPages.length+' 页'}</span></div><div class="side-list">${S.file?'<p class="tiny muted">真实 PDF 由浏览器原生查看器呈现。当前原型不解析或编辑原始 PDF。</p>':S.pdfPages.map(n=>`<button class="thumb ${n===S.pdfPage?'active':''}" data-action="pdf-page" data-page="${n}" ${n===S.pdfPage?'aria-current="true"':''}><span class="thumb-paper"><b>实验记录</b><i></i><i></i><i></i><span>图 2-${n}</span><i></i><i></i></span><small>第 ${n} 页${S.rotations[n]?' · 横向':''}</small></button>`).join('')}</div><div class="side-foot">${S.file?'文件未上传':'自编示例 · 页面操作仅改变原型状态'}</div></aside><main class="view">${S.file?'':`<div class="docbar"><div class="group-controls" role="group" aria-label="页面显示方式">${btn('单页','pdf-mode',S.pdfMode==='single'?'active':'','','data-mode="single"')}${btn('双页','pdf-mode',S.pdfMode==='double'?'active':'','','data-mode="double"')}</div><div class="divider"></div>${ib('缩小','zoom-out','minus')}${btn(S.fit?'适应窗口':S.zoom+'%','zoom-reset','text')}${ib('放大','zoom-in','plus')}${btn('适应窗口','fit',S.fit?'active':'')}<div class="sp"></div>${ib('上一页','pdf-prev','back',idx===0?'disabled':'')}<label for="pageInput" class="tiny muted">页码</label><input id="pageInput" class="page-input" type="number" min="1" max="6" value="${S.pdfPage}" aria-label="跳转页码">${ib('下一页','pdf-next','arrow',idx===S.pdfPages.length-1?'disabled':'')}</div>`}${S.pdfDirty&&!S.file?`<div class="notice"><p>页面布局已修改，原件保持不变。</p>${btn('撤销','pdf-undo','text','undo',!S.undo.length?'disabled':'')}${btn('导出布局记录','pdf-save','','download')}${btn('放弃修改','pdf-discard','text')}</div>`:''}<div class="reader-scroll" id="readerScroll">${S.file?`<iframe class="file-frame" src="${S.file.url}" title="本机 PDF 文件"></iframe>`:`<div class="pdf-stage ${S.pdfMode==='double'?'double':''}">${shown.map(pdfPage).join('')}</div>`}</div>${status(S.file?'本地 PDF 预览 · 原始文件未修改':`第 ${S.pdfPage} / ${S.pdfPages.length} 页 · ${S.pdfMode==='double'?'双页（窄窗口显示当前页）':'单页'}`,S.file?btn('返回示例','close-file','text'):'<span>示例布局操作 · 不生成已编辑 PDF</span>')}</main></div></div>`}
function aiPanel(){return `<aside class="inspector" aria-label="AI 助手"><div class="inspector-head"><h2>AI 助手</h2><div class="sp"></div><span class="local-label">本地演示</span><div class="group-controls" style="width:100%">${['对话','总结','翻译'].map(x=>btn(x,'ai-operation',S.operation===x?'active':'','',`data-value="${x}"`)).join('')}</div><label class="tiny muted" for="aiScope">上下文范围</label><select id="aiScope" style="flex:1;width:auto"><option ${S.aiScope==='当前章'?'selected':''}>当前章</option><option ${S.aiScope==='选区'?'selected':''} ${!S.selection?'disabled':''}>选区</option><option ${S.aiScope==='全文'?'selected':''}>全文</option></select></div><div class="inspector-body" id="chatScroll">${!S.chat.length?`<div class="eyebrow">围绕原文思考</div><p>可以从一个具体问题开始。</p>${btn('这一章的核心观点是什么？','ai-suggest','text')}<p class="tiny muted">本原型只演示核对、停止和引用回跳，不发送请求。</p>`:S.chat.map(c=>`<div class="chat-item ${c.role==='user'?'user':''}"><span class="who">${c.role==='user'?'你':'示例回答 · 非模型生成'}</span><div>${esc(c.text)}</div>${c.role==='assistant'?btn('查看引用 · 第 '+(c.chapter+1)+' 章','ai-cite','citation','arrow',`data-chapter="${c.chapter}" data-para="${c.para}"`):''}</div>`).join('')}${S.busy?'<div class="progress" aria-label="演示回答生成中"></div><p class="tiny muted">正在准备示例回答…</p>'+btn('停止','ai-stop','text'):''}</div><div class="composer"><label for="question">${S.operation==='对话'?'你的问题':S.operation+'要求'}</label><textarea id="question" placeholder="例如：这个观点有哪些前提？" ${S.busy?'disabled':''}>${esc(S.draft||'')}</textarea>${btn(S.operation==='对话'?'核对并发送':'核对并'+S.operation,'ai-preview','primary','arrow',S.busy?'disabled':'')}<span class="tiny muted">发送前始终核对内容与范围</span></div></aside>`}
function matched(){const terms=S.query.trim().split(/\s+/).filter(Boolean);return corpus.filter(x=>S.scope.includes(x.doc)&&(!terms.length||(S.match==='all'?terms.every(t=>x.text.toLowerCase().includes(t.toLowerCase())):terms.some(t=>x.text.toLowerCase().includes(t.toLowerCase())))))}
function highlight(t){const terms=S.query.trim().split(/\s+/).filter(Boolean).sort((a,b)=>b.length-a.length);if(!terms.length)return esc(t);const re=new RegExp('('+terms.map(x=>x.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','gi');return t.split(re).map((v,i)=>i%2?'<mark>'+esc(v)+'</mark>':esc(v)).join('')}
function deck(){return `<aside class="inspector" ${S.deckOpen?'':'hidden'}><div class="inspector-head"><h2>引用集 · ${S.deck.length}</h2><div class="sp"></div>${ib('收起引用集','toggle-deck','close')}</div><div class="inspector-body">${S.deck.length?S.deck.map(id=>{const x=corpus.find(v=>v.id===id);if(!x)return '';return `<section class="cite-entry"><p>${esc(x.text)}</p><button class="text tiny linklike" data-action="jump" data-id="${x.id}">${docs.find(d=>d.id===x.doc).name} · ${x.loc}${icon('arrow')}</button><label class="od-field tiny muted" for="memo-${x.id}">我的笔记<textarea id="memo-${x.id}" data-memo="${x.id}" placeholder="记录它与问题的关系">${esc((S.memos||{})[x.id]||'')}</textarea></label><div class="od-row" style="margin-top:8px">${btn('复制','copy-cite','text','copy',`data-id="${x.id}"`)}${btn('移除','unpin','text danger','',`data-id="${x.id}"`)}</div></section>`}).join(''):'<p class="muted">把值得留下的结果加入这里。</p><p class="tiny muted">每条引用都保留来源，方便回到上下文。</p>'}</div><div class="composer">${btn('导出引用集','export-deck','','download',!S.deck.length?'disabled':'')}<span class="tiny muted">保存于此浏览器，可导出 Markdown</span></div></aside>`}
function research(){const hits=matched();return `<main class="workspace research-layout ${S.side?'side-visible':''}"><aside class="side ${S.side?'mobile-open':''}" ${S.side?'':'hidden'}><div class="side-head"><h2>检索范围</h2></div><p class="tiny muted">示例文档 · ${S.scope.length} 份已选</p>${docs.map(d=>`<label class="scope-row"><input type="checkbox" data-scope="${d.id}" ${S.scope.includes(d.id)?'checked':''}><span class="od-field"><span>${d.name}</span><small class="muted">${d.ext} · 自编示例</small></span></label>`).join('')}<div class="side-foot">检索在本地示例文本中进行，不调用 AI。</div></aside><section class="view"><div class="research-top"><div class="od-row"><h1 class="od-fill">研究工作台</h1>${ib('检索范围','sidebar','side',`aria-expanded="${S.side}"`)}${btn('引用集 '+S.deck.length,'toggle-deck',S.deckOpen?'active':'','book',`aria-expanded="${S.deckOpen}"`)}</div><label for="searchInput" class="tiny muted" style="display:block;margin-bottom:8px">在所选文档中查找</label><div class="searchrow"><input id="searchInput" value="${esc(S.query)}" placeholder="输入关键词，以空格分隔">${btn('检索','search','primary','search')}</div><div class="search-meta"><label><input type="radio" name="match" value="any" ${S.match==='any'?'checked':''}>任一词匹配</label><label><input type="radio" name="match" value="all" ${S.match==='all'?'checked':''}>全部词匹配</label><span>${S.scope.length} 份文档 · ${hits.length} 处命中</span></div></div><div class="reader-scroll"><div class="result-list">${!S.scope.length?'<div class="empty"><h2>先选择检索范围</h2><p>从检索范围中勾选至少一份文档。</p>'+btn('选择文档','show-scope')+'</div>':!hits.length?'<div class="empty"><h2>没有找到匹配内容</h2><p>缩短关键词，或改用“任一词匹配”。</p>'+btn('清除关键词','clear-search')+'</div>':hits.map(x=>`<article class="result"><h2>${docs.find(d=>d.id===x.doc).name} · ${x.loc}</h2><p>${highlight(x.text)}</p><div class="actions">${btn('查看原文','jump','text','arrow',`data-id="${x.id}"`)}${btn('复制引用','copy-cite','text','copy',`data-id="${x.id}"`)}${btn(S.deck.includes(x.id)?'已加入':'加入引用集','pin',S.deck.includes(x.id)?'active':'text',S.deck.includes(x.id)?'check':'plus',`data-id="${x.id}" aria-pressed="${S.deck.includes(x.id)}"`)}</div></article>`).join('')}</div></div>${status('跨文档检索与引用整理 · 付费能力原型探索','<span>未接入付费或授权服务</span>')}</section>${deck()}</main>`}
function settings(){return `<main class="reader-scroll"><div class="settings"><div class="od-row"><h1 class="od-fill">设置</h1>${btn('返回阅读','nav','text','back','data-to="reading"')}</div><section class="settings-section"><h2>外观与阅读</h2><div class="setting-row"><label for="appTheme">应用外观</label><select id="appTheme"><option value="light" ${S.theme==='light'?'selected':''}>浅色</option><option value="dark" ${S.theme==='dark'?'selected':''}>深色</option></select></div><div class="setting-row"><label for="readTheme">阅读纸张</label><div><select id="readTheme">${[['follow','跟随应用'],['paper','纸张'],['sepia','深纸'],['night','夜间']].map(([v,l])=>`<option value="${v}" ${S.settings.readTheme===v?'selected':''}>${l}</option>`).join('')}</select><small>仅改变 EPUB 正文，不改变 PDF 原始页面。</small></div></div>${[['font','正文字号',16,26,1,S.settings.font,'px'],['line','行间距',1.5,2.1,.1,S.settings.line,''],['width','版心宽度',480,760,40,S.settings.width,'px']].map(([id,label,min,max,step,value,unit])=>`<div class="setting-row"><label for="${id}">${label}</label><div><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"><small id="value-${id}">${value}${unit}</small></div></div>`).join('')}<p class="tiny muted">外观与阅读设置即时保存。${storage?'保存在此浏览器。':'当前环境禁用存储，仅本次会话有效。'}</p></section>${agentSettings()}<section class="settings-section"><h2>AI 服务</h2><p class="muted">本原型仅提供本地交互演示。以下配置不会发起网络请求。</p><div class="setting-row"><label for="provider">服务商名称</label><input id="provider" value="${esc(S.settings.provider==='未配置'?'':S.settings.provider)}" placeholder="填写服务商名称"></div><div class="setting-row"><label for="baseUrl">服务地址</label><input id="baseUrl" type="url" value="${esc(S.settings.url)}" placeholder="https://"></div><div class="setting-row"><label for="model">模型名称</label><input id="model" value="${esc(S.settings.model)}" placeholder="填写模型名称"></div><p class="tiny muted" id="configError" hidden></p><div class="od-row">${btn('保存服务配置','save-config','primary')}<span class="tiny muted" id="configStatus">未接入真实服务</span></div><p class="tiny muted">原型不收集或保存 API Key。正式应用的凭据与发送策略以设计契约为准。</p></section><section class="settings-section"><h2>批注与引用</h2><p class="muted">${S.notes.length} 条批注 · ${S.deck.length} 条引用</p><div class="od-cluster">${btn('导出批注','export-notes','','download')}${btn('导出引用集','export-deck','','download',!S.deck.length?'disabled':'')}</div><p class="tiny muted">原型数据与原始文档分离，不会修改你的文件。</p></section></div></main>`}
function render(){applyTheme();const app=$('#app');app.innerHTML=header()+(S.screen==='welcome'?welcome():S.screen==='agent'?agentView():S.screen==='pdf'?(A.source?agentDocument():pdf()):S.screen==='research'?research():S.screen==='settings'?settings():reading(S.screen==='ai'));document.title='Booklight · '+({welcome:'继续阅读',pdf:'PDF 阅读',reading:'阅读',ai:'AI 助手',research:'研究工作台',settings:'设置',agent:'Agent 任务'}[S.screen]);}
function capture(){const r=$('#readerScroll');if(r&&['reading','ai'].includes(S.screen))S.scroll=r.scrollTop;if($('#question'))S.draft=$('#question').value}
function navigate(to){capture();S.screen=to;render();const r=$('#readerScroll');if(r&&['reading','ai'].includes(to))r.scrollTop=S.scroll;const focus=$('main h1')||$('.docname')||$('.brand');if(focus){focus.setAttribute('tabindex','-1');focus.focus({preventScroll:true})}}
function showDialog(html){dialogBack=document.activeElement;const d=$('#dialog');d.innerHTML=html;d.showModal();const f=$('textarea,input,button',d);if(f)f.focus()}
function closeDialog(){const d=$('#dialog');d.close();if(dialogBack?.isConnected)dialogBack.focus();else $('.brand')?.focus()}
function changedNotes(){S.save='saving';render();setTimeout(()=>{S.save=persist()?'saved':'error';render();if(S.save==='error')announce('存储不可用，请导出批注保留副本')},450)}
function addNote(note='',color='yellow'){if(!S.selection)return;S.notes.push({id:crypto.randomUUID(),text:S.selection,note,chapter:S.chapter,para:S.selectionPara,color});S.selection='';window.getSelection()?.removeAllRanges();changedNotes();announce('批注已添加')}
function noteDialog(existing){const n=existing?S.notes.find(n=>n.id===existing):null;const t=n?.text||S.selection;if(!t){announce('请先选中一段正文');return}showDialog(`<h2>${n?'编辑批注':'添加笔记'}</h2><p>${esc(t)}</p><label for="noteText" class="tiny muted">我的笔记</label><textarea id="noteText" rows="4">${esc(n?.note||'')}</textarea><div class="dialog-actions">${btn('取消','dialog-close')}${btn('保存笔记','note-save','primary','',n?`data-id="${n.id}"`:'')}</div>`)}
function pdfSnapshot(){S.undo.push({pages:[...S.pdfPages],rotations:{...S.rotations},page:S.pdfPage});S.pdfDirty=true}
function aiText(){if(S.aiScope==='选区')return S.selection;if(S.aiScope==='全文')return chapters.map(c=>c.title+'\n'+c.paras.join('\n\n')).join('\n\n');return chapters[S.chapter].title+'\n'+chapters[S.chapter].paras.join('\n\n')}
function aiPreview(){S.draft=$('#question').value.trim();if(!S.draft&&S.operation==='对话'){$('#question').focus();announce('请先写下问题');return}const content=aiText(),history=S.chat.map(x=>(x.role==='user'?'用户：':'助手：')+x.text).join('\n');S.pendingAI={content,history,question:S.draft,chapter:S.chapter,para:S.selection?S.selectionPara:2};const count=x=>Array.from(x).length;showDialog(`<h2>核对即将发送的内容</h2><p class="muted">这是本地演示；确认后不会向外部服务发送数据。</p><dl><dt>服务商</dt><dd>${esc(S.settings.provider)} · 演示模式</dd><dt>操作与范围</dt><dd>${S.operation} · ${S.aiScope}</dd><dt>文档</dt><dd>阅读与理解</dd><dt>你的问题</dt><dd>${esc(S.draft||S.operation+'所选内容')}</dd></dl><details><summary>展开实际内容与精确字符数</summary><p>文档 ${count(content)} · 历史 ${count(history)} · 问题 ${count(S.draft)} · 合计 ${count(content)+count(history)+count(S.draft)} 字符</p><pre>${esc(content+'\n\n'+(history?'会话历史：\n'+history+'\n\n':'')+'问题：'+S.draft)}</pre></details><div class="dialog-actions">${btn('取消','dialog-close')}${btn('继续本地演示','ai-send','primary')}</div>`)}
function copy(t){if(navigator.clipboard?.writeText)navigator.clipboard.writeText(t).then(()=>announce('已复制')).catch(()=>copyFallback(t));else copyFallback(t)}
function copyFallback(t){showDialog('<h2>复制内容</h2><p>当前环境不允许直接访问剪贴板，请手动复制。</p><textarea id="copyText" rows="6">'+esc(t)+'</textarea><div class="dialog-actions">'+btn('完成','dialog-close')+'</div>');$('#copyText').select()}
function citation(x){return '“'+x.text+'”\n——《'+docs.find(d=>d.id===x.doc).name+'》 · '+x.loc+'（Booklight 自编示例）'}
function jump(x){capture();S.returnTo='research';if(x.doc==='pdf'){S.pdfPage=x.page;navigate('pdf')}else{S.chapter=x.chapter;S.scroll=0;navigate('reading');$('#para-'+x.para)?.scrollIntoView({block:'center'});$('#para-'+x.para)?.animate([{background:'var(--soft)'},{background:'transparent'}],{duration:matchMedia('(prefers-reduced-motion: reduce)').matches?0:900})}}
function fileOpen(file){if(!file)return;if(file.type!=='application/pdf'&&!file.name.toLowerCase().endsWith('.pdf')){announce('本轮原型支持本机 PDF 预览；EPUB 请使用内置阅读示例');return}if(S.file)URL.revokeObjectURL(S.file.url);S.file={name:file.name,url:URL.createObjectURL(file)};navigate('pdf');announce('文件在本机打开，未上传')}
const actions={
'pdf-ai':()=>showDialog('<h2>PDF 与 AI</h2><p>此轮 AI 交互使用《阅读与理解》的自编 EPUB 文本。当前 PDF 不会被提取或发送。</p><div class="dialog-actions">'+btn('留在 PDF','dialog-close')+btn('打开 EPUB 助手','pdf-ai-open','primary')+'</div>'),'pdf-ai-open':()=>{closeDialog();navigate('ai')},
nav:b=>{if(b.dataset.to==='pdf')A.source=null;navigate(b.dataset.to)},theme:()=>{capture();S.theme=S.theme==='light'?'dark':'light';saveTheme();persist();render();$('[data-action="theme"]')?.focus()},open:()=>$('#fileInput').click(),sidebar:()=>{capture();S.side=!S.side;render()},'show-scope':()=>{S.side=true;render()},'side-tab':b=>{S.sideTab=b.dataset.tab;render()},chapter:b=>{S.chapter=+b.dataset.n;S.selection='';S.scroll=0;persist();navigate('reading')},'chapter-prev':()=>{S.chapter=Math.max(0,S.chapter-1);S.scroll=0;persist();render()},'chapter-next':()=>{S.chapter=Math.min(2,S.chapter+1);S.scroll=0;persist();render()},bookmark:()=>{S.bookmark=!S.bookmark;render();announce(S.bookmark?'已添加本章书签（本次会话）':'已移除书签')},typeset:()=>{showDialog('<h2>阅读排版</h2><p>调整正文大小、行距和版心宽度。设置会保留，返回后继续阅读。</p><div class="dialog-actions">'+btn('取消','dialog-close')+btn('前往阅读设置','typeset-open','primary')+'</div>')},'typeset-open':()=>{closeDialog();navigate('settings')},highlight:b=>addNote('',b.dataset.color),'note-new':()=>noteDialog(),'note-edit':b=>noteDialog(b.dataset.id),'note-save':b=>{const value=$('#noteText').value.trim();if(b.dataset.id){const n=S.notes.find(n=>n.id===b.dataset.id);n.note=value;closeDialog();changedNotes()}else{closeDialog();addNote(value)}},'note-delete':b=>showDialog('<h2>删除这条批注？</h2><p>正文不会改变，此操作仅移除高亮与笔记。</p><div class="dialog-actions">'+btn('取消','dialog-close')+btn('删除批注','note-delete-confirm','danger','',`data-id="${b.dataset.id}"`)+'</div>'),'note-delete-confirm':b=>{S.notes=S.notes.filter(n=>n.id!==b.dataset.id);closeDialog();changedNotes()},'note-jump':b=>{const n=S.notes.find(n=>n.id===b.dataset.id);S.chapter=n.chapter;render();$('#para-'+n.para)?.scrollIntoView({block:'center'})},'export-notes':()=>download('booklight-annotations.json',JSON.stringify({format:'booklight-prototype-notes-v1',document:'阅读与理解（自编示例）',notes:S.notes},null,2)),'clear-selection':()=>{S.selection='';window.getSelection()?.removeAllRanges();render()},'copy-selection':()=>copy(S.selection),'selection-ai':()=>{S.aiScope='选区';navigate('ai')},'return-results':()=>{S.returnTo=null;navigate('research')},'pdf-mode':b=>{S.pdfMode=b.dataset.mode;S.fit=true;render()},'pdf-page':b=>{S.pdfPage=+b.dataset.page;render()},'pdf-prev':()=>{S.pdfPage=S.pdfPages[Math.max(0,S.pdfPages.indexOf(S.pdfPage)-1)];render()},'pdf-next':()=>{S.pdfPage=S.pdfPages[Math.min(S.pdfPages.length-1,S.pdfPages.indexOf(S.pdfPage)+1)];render()},'zoom-in':()=>{S.fit=false;S.pdfMode='single';S.zoom=Math.min(160,S.zoom+10);render()},'zoom-out':()=>{S.fit=false;S.pdfMode='single';S.zoom=Math.max(50,S.zoom-10);render()},'zoom-reset':()=>{S.fit=false;S.zoom=100;S.pdfMode='single';render()},fit:()=>{S.fit=true;render()},'pdf-menu':()=>showDialog(`<h2>第 ${S.pdfPage} 页</h2><p class="muted">以下操作仅编辑示例页面布局。原型不修改或导出真实 PDF。</p><div class="menu-grid">${btn('切换页面方向','pdf-rotate','','rotate')}${btn('删除当前页','pdf-delete','danger','trash',S.pdfPages.length===1?'disabled':'')}${btn('撤销上次编辑','pdf-undo','','undo',!S.undo.length?'disabled':'')}</div><div class="dialog-actions">${btn('关闭','dialog-close')}</div>`),'pdf-rotate':()=>{pdfSnapshot();S.rotations[S.pdfPage]=(S.rotations[S.pdfPage]||0)+90;closeDialog();render();announce('示例页面已切换方向')},'pdf-delete':()=>{showDialog(`<h2>删除第 ${S.pdfPage} 页？</h2><p>仅从示例布局移除，之后可以撤销。</p><div class="dialog-actions">${btn('取消','dialog-close')}${btn('删除页面','pdf-delete-confirm','danger')}</div>`)},'pdf-delete-confirm':()=>{pdfSnapshot();S.pdfPages=S.pdfPages.filter(n=>n!==S.pdfPage);S.pdfPage=S.pdfPages[0];closeDialog();render()},'pdf-undo':()=>{const old=S.undo.pop();if(old){S.pdfPages=old.pages;S.rotations=old.rotations;S.pdfPage=old.page;S.pdfDirty=S.undo.length>0}if($('#dialog').open)closeDialog();render()},'pdf-discard':()=>showDialog('<h2>放弃全部页面修改？</h2><p>示例页面将恢复最初的顺序与方向。</p><div class="dialog-actions">'+btn('取消','dialog-close')+btn('放弃修改','pdf-discard-confirm','danger')+'</div>'),'pdf-discard-confirm':()=>{S.pdfPages=[1,2,3,4,5,6];S.rotations={};S.undo=[];S.pdfDirty=false;closeDialog();render()},'pdf-save':()=>{download('booklight-page-layout.json',JSON.stringify({type:'prototype-layout-not-pdf',pages:S.pdfPages,rotations:S.rotations},null,2));S.pdfDirty=false;render();announce('已导出布局记录；没有生成或修改 PDF')},'close-file':()=>{URL.revokeObjectURL(S.file.url);S.file=null;render()},'ai-operation':b=>{capture();S.operation=b.dataset.value;render()},'ai-suggest':()=>{$('#question').value='这一章的核心观点是什么？';$('#question').focus()},'ai-preview':aiPreview,'ai-send':()=>{const p=S.pendingAI;closeDialog();S.chat.push({role:'user',text:p.question||S.operation+'所选内容'});S.busy=true;S.draft='';render();timer=setTimeout(()=>{S.busy=false;const answer=S.operation==='翻译'?'固定译文示例（不实时翻译所选内容）：When excerpts remain connected to their source, notes gain a place to return to.':S.operation==='总结'?'本章示例摘要：摘录需要保留上下文；跨文档阅读需要比较前提；研究整理应区分证据、推论与猜想。':'这个示例问题可以从“摘录与上下文的连接”入手。判断一条摘录是否有用，需要回到原文检查它回应的问题与适用条件。以下引用提供了返回正文的入口。';S.chat.push({role:'assistant',text:answer,chapter:p.chapter,para:p.para});render();announce('示例回答已完成，未调用外部 AI')},1500)},'ai-stop':()=>{clearTimeout(timer);S.busy=false;render();announce('已停止本地演示')},'ai-cite':b=>{S.chapter=+b.dataset.chapter;S.scroll=0;navigate('reading');$('#para-'+b.dataset.para)?.scrollIntoView({block:'center'})},search:()=>{S.query=$('#searchInput').value;render();$('#searchInput')?.focus()},'clear-search':()=>{S.query='';render()},'toggle-deck':()=>{S.deckOpen=!S.deckOpen;render()},pin:b=>{const id=b.dataset.id;if(S.deck.includes(id)){S.deck=S.deck.filter(x=>x!==id)}else S.deck.push(id);persist();render();$(`[data-action="pin"][data-id="${id}"]`)?.focus()},unpin:b=>{S.deck=S.deck.filter(x=>x!==b.dataset.id);persist();render();$('[data-action="toggle-deck"]')?.focus()},jump:b=>jump(corpus.find(x=>x.id===b.dataset.id)),'copy-cite':b=>copy(citation(corpus.find(x=>x.id===b.dataset.id))),'export-deck':()=>download('booklight-citations.md','# 引用集\n\n'+S.deck.map(id=>{const x=corpus.find(v=>v.id===id);return citation(x)+((S.memos||{})[id]?'\n\n笔记：'+S.memos[id]:'')}).join('\n\n---\n\n'),'text/markdown;charset=utf-8'),'save-config':()=>{const url=$('#baseUrl').value.trim();const error=$('#configError');if(url&&!/^https?:\/\/[^\s]+$/.test(url)){error.textContent='请输入以 https:// 或 http:// 开头的完整服务地址';error.hidden=false;$('#baseUrl').focus();return}S.settings.provider=$('#provider').value.trim()||'未配置';S.settings.url=url;S.settings.model=$('#model').value.trim();persist();error.hidden=true;$('#configStatus').textContent=storage?'配置已保存 · 演示模式':'配置仅在本次会话有效';announce('服务配置已保存；未发起网络请求')},'dialog-close':closeDialog};
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;actions[b.dataset.action]?.(b)});
document.addEventListener('change',e=>{const t=e.target;if(t.matches('[data-scope]')){S.scope=t.checked?[...new Set([...S.scope,t.dataset.scope])]:S.scope.filter(x=>x!==t.dataset.scope);render()}else if(t.name==='match'){S.match=t.value;S.query=$('#searchInput').value;render()}else if(t.id==='aiScope'){S.aiScope=t.value}else if(t.id==='pageInput'){const n=+t.value;if(S.pdfPages.includes(n)){S.pdfPage=n;render()}else{t.value=S.pdfPage;announce('该页不存在于当前示例布局')}}else if(t.id==='appTheme'){S.theme=t.value;saveTheme();persist();applyTheme();syncThemeToggle()}else if(t.id==='readTheme'){S.settings.readTheme=t.value;persist()}else if(t.matches('[data-memo]')){S.memos=S.memos||{};S.memos[t.dataset.memo]=t.value;persist()}});
document.addEventListener('input',e=>{const t=e.target;if(['font','line','width'].includes(t.id)){S.settings[t.id]=+t.value;$('#value-'+t.id).textContent=t.value+(t.id==='line'?'':'px');persist();applyTheme()}if(t.id==='question')S.draft=t.value});
document.addEventListener('keydown',e=>{if(e.key==='Enter'&&e.target.id==='searchInput'){e.preventDefault();actions.search()}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='o'){e.preventDefault();$('#fileInput').click()}if(e.key==='Escape'&&!$('#dialog').open&&S.selection){S.selection='';render()}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&e.target.id==='question'){e.preventDefault();aiPreview()}});
document.addEventListener('pointerup',e=>{if(e.target.closest('button,textarea,input,select,dialog'))return;setTimeout(()=>{const sel=window.getSelection();if(!sel||sel.isCollapsed)return;const node=sel.anchorNode?.parentElement;const end=sel.focusNode?.parentElement;const p=node?.closest('#prose p[data-para]'),q=end?.closest('#prose p[data-para]');if(!p||p!==q)return;S.selection=sel.toString().trim();S.selectionPara=+p.dataset.para;selectionRange=sel.getRangeAt(0).cloneRange();const tools=$('#selectionTools');if(tools){tools.hidden=false;$('span',tools).textContent='已选 '+Array.from(S.selection).length+' 字符'}},0)});
document.addEventListener('keyup',e=>{if(!e.shiftKey)return;const sel=window.getSelection();if(!sel||sel.isCollapsed)return;const a=sel.anchorNode?.parentElement?.closest('#prose p[data-para]');const b=sel.focusNode?.parentElement?.closest('#prose p[data-para]');if(!a||a!==b)return;S.selection=sel.toString().trim();S.selectionPara=+a.dataset.para;const tools=$('#selectionTools');if(tools){tools.hidden=false;$('span',tools).textContent='已选 '+Array.from(S.selection).length+' 字符'}});
$('#dialog').addEventListener('cancel',()=>setTimeout(()=>{if(dialogBack?.isConnected)dialogBack.focus();else $('.brand')?.focus()},0));
$('#fileInput').addEventListener('change',e=>{fileOpen(e.target.files[0]);e.target.value=''});
document.addEventListener('dragover',e=>{e.preventDefault()});document.addEventListener('drop',e=>{e.preventDefault();fileOpen(e.dataTransfer.files[0])});

// Product prototype: all agent operations below use local, authored sample data.
const agentDocs=[
 {id:'lab-a',name:'光学实验记录',revision:1,pages:3,blocks:[
  {page:1,title:'实验目标与记录范围',text:'为了比较不同时间的测量结果，需要同时记录光路、采样方式与环境条件。实验记录应让另一个读者能够理解测量发生的背景。',rect:[.12,.28,.76,.18]},
  {page:2,title:'测量条件',text:'测量条件包括环境温度、振动状态、采样率和采样窗口。只有这些条件保持一致，测量结果才具有直接可比性。',rect:[.12,.28,.76,.18]},
  {page:3,title:'原始记录与复核',text:'分析测量差异前，应保留原始数据与处理步骤。发现异常时，先复核环境条件与设备配置，再判断观测差异的来源。',rect:[.12,.28,.76,.18]}
 ]},
 {id:'lab-b',name:'复测与误差核对',revision:1,pages:3,blocks:[
  {page:1,title:'复测的前提',text:'复测并非简单重复一次读数。开始复测之前，应核对仪器设置、参考光路和样品位置，并说明与首次测量相比有哪些变化。',rect:[.12,.28,.76,.18]},
  {page:2,title:'跨次测量的可比性',text:'环境条件的变化可能影响测量的可比性。比较两组结果时，应将温度、振动与采样设置作为共同的核对项目。',rect:[.12,.28,.76,.18]},
  {page:3,title:'结论的边界',text:'记录可以支持条件范围内的结论，但不应把未经核对的变化直接归结为单一原因。对存在疑问的证据，应标记并保留原文出处。',rect:[.12,.28,.76,.18]}
 ]}
];
const A={connected:false,grant:{docs:['lab-a','lab-b'],read:true,annotate:false,edit:false,external:false},grantVersion:0,task:null,evidence:[],proposals:[],annotations:[],layouts:{},audit:[],transactions:[],source:null,returnScreen:'agent',tick:null,epoch:0,objective:'找出影响测量可比性的条件，整理证据并建议批注',keywords:'测量 条件',selectedDocs:['lab-a','lab-b'],packet:null,pendingApply:null};
function aid(prefix){return prefix+'-'+crypto.randomUUID()}
function agentLog(action,detail){A.audit.push({id:aid('event'),at:new Date().toISOString(),actor:'local-demo-agent',action,detail});}
function docById(id){return agentDocs.find(d=>d.id===id)}
function revision(id){return docById(id)?.revision}
function localAnchor(doc,block){return {document_id:doc.id,revision:doc.revision,page_index:block.page-1,page_label:String(block.page),coordinate_space:'normalized-cropbox-top-left-unrotated',rect:block.rect,quote:{exact:block.text,prefix:'',suffix:''},extraction:'authored-demo-text',confidence:null}}
function canRead(id){return A.connected&&A.grant.read&&A.grant.docs.includes(id)}
function agentStatus(){return {running:'执行中',review:'待核对',completed:'已处理',paused:'已接管',cancelled:'已停止',failed:'需要恢复',no_results:'无匹配结果'}[A.task?.status]||'未开始'}
function taskBanner(){return `<button class="text agent-entry ${S.screen==='agent'?'active':''}" data-action="nav" data-to="agent" ${S.screen==='agent'?'aria-current="page"':''}>${icon('spark')}<span>Agent${A.task?' · '+agentStatus():''}</span></button>`}
function grantSummary(){return A.connected?`本地示例 Agent · ${A.grant.docs.length} 份文档 · ${A.grant.read?'读取':''}${A.grant.annotate?' / 批注':''}${A.grant.edit?' / 页面修改':''}`:'尚未连接 · 仅演示授权交互'}
function agentSettings(){return `<section class="settings-section" id="agentConnection"><div class="od-row"><h2 class="od-fill">Agent 连接与权限</h2><span class="agent-label">本地演示</span></div><p class="muted">${grantSummary()}</p><p class="tiny muted">连接仅在本次页面会话有效；这不是运行中的 MCP 服务，也不会连接其他应用。</p><div class="agent-grants">${agentDocs.map(d=>`<div class="od-row"><span class="od-field od-fill"><span>${d.name}</span><small>自编 PDF 版式示例 · ${d.pages} 页 · 版本 ${d.revision}</small></span><span class="tiny muted">${A.connected&&A.grant.docs.includes(d.id)?'已授权':'未授权'}</span></div>`).join('')}</div><div class="od-cluster">${btn(A.connected?'调整授权':'连接示例 Agent','agent-connect',A.connected?'':'primary','spark')}${A.connected?btn('撤销全部授权','agent-revoke','danger'):''}${btn('打开任务','nav','text','arrow','data-to="agent"')}</div><p class="tiny muted">读取、批注、页面修改分开授权。外发默认关闭；本原型不提供外发能力。</p></section>`}
function grantDialog(){showDialog(`<h2>${A.connected?'调整访问授权':'连接本地示例 Agent'}</h2><p>授权对象：本地示例 Agent。仅在此页面会话中生效，不创建真实连接。</p><fieldset class="agent-fieldset"><legend>允许访问的文档</legend>${agentDocs.map(d=>`<label class="scope-row"><input type="checkbox" name="agentDoc" value="${d.id}" ${A.grant.docs.includes(d.id)?'checked':''}><span>${d.name}<small class="muted" style="display:block">自编示例 · 不含你打开的本机文件</small></span></label>`).join('')}</fieldset><fieldset class="agent-fieldset"><legend>允许的操作</legend><label class="scope-row"><input id="grantRead" type="checkbox" ${A.grant.read?'checked':''}><span>读取与检索<small class="muted" style="display:block">读取文本、页面位置与文档版本</small></span></label><label class="scope-row"><input id="grantNote" type="checkbox" ${A.grant.annotate?'checked':''}><span>写入批注<small class="muted" style="display:block">允许应用已核对的批注提案</small></span></label><label class="scope-row"><input id="grantEdit" type="checkbox" ${A.grant.edit?'checked':''}><span>修改示例页面布局<small class="muted" style="display:block">不修改原始文件，可撤销</small></span></label><p class="tiny muted">外发：关闭。本原型不提供此能力。</p></fieldset><p id="grantError" class="agent-error" hidden></p><div class="dialog-actions">${btn('取消','dialog-close')}${btn('授权本次会话','agent-authorize','primary')}</div>`)}
function taskForm(){return `<section class="agent-compose"><div class="eyebrow">人与 AGENT 共用一份原文</div><h1>把查找交给 Agent，<br>把判断留给自己。</h1><p class="muted">跨文档找到证据，核对来处，再把有用的发现留在页边。</p><label for="agentObjective">任务目标</label><textarea id="agentObjective" rows="2">${esc(A.objective)}</textarea><label for="agentKeywords">检索关键词</label><input id="agentKeywords" value="${esc(A.keywords)}" placeholder="以空格分隔，任一词匹配"><p class="tiny muted">本地演示按关键词查找自编文本，不理解或执行任意自然语言指令。</p><fieldset class="agent-fieldset"><legend>任务文档</legend>${agentDocs.map(d=>`<label class="scope-row"><input type="checkbox" name="taskDoc" value="${d.id}" ${A.selectedDocs.includes(d.id)?'checked':''}><span>${d.name}<small class="muted" style="display:block">${d.pages} 页 · 自编 PDF 版式示例${canRead(d.id)?' · 可读取':' · 尚未授权'}</small></span></label>`).join('')}</fieldset><p id="agentFormError" class="agent-error" hidden></p><div class="od-cluster">${btn(A.connected?'开始任务':'连接并开始','agent-start','primary','arrow')}${btn('查看连接权限','agent-connect','text','settings')}</div><p class="tiny muted">仅检索所选且已授权的文档，不会读取本机 PDF、上传文件或连接外部模型。</p></section>`}
function taskSteps(){const t=A.task;const phase=t?.phase||0;return `<ol class="agent-steps" aria-label="任务阶段">${['核对访问范围','检索文档','整理出处','生成修改提案'].map((x,i)=>`<li class="${phase>i?'done':phase===i?'current':''}"><span class="step-number">${phase>i?icon('check'):i+1}</span><span>${x}</span><small>${phase>i?'已完成':phase===i&&t.status==='running'?'进行中':'待处理'}</small></li>`).join('')}</ol>`}
function proposalCard(v){const d=docById(v.documentId);const applied=v.status==='applied';const pending=v.status==='pending';return `<article class="agent-proposal"><div class="od-row"><label class="od-row od-fill"><input type="checkbox" data-proposal="${v.id}" ${v.selected&&pending?'checked':''} ${pending?'':'disabled'}><span>${v.type==='annotation'?'添加批注':'切换页面方向'}</span></label><span class="tiny muted">${{pending:'待核对',applied:'已应用',rejected:'已拒绝',undone:'已撤销'}[v.status]}</span></div><p class="tiny muted">${d.name} · 第 ${v.anchor.page_index+1} 页 · 版本 ${v.baseRevision}</p>${v.type==='annotation'?`<p class="proposal-quote">${esc(v.anchor.quote.exact)}</p><label class="tiny muted od-field" for="proposal-${v.id}">拟添加的笔记<textarea id="proposal-${v.id}" data-proposal-note="${v.id}" rows="2" ${pending?'':'disabled'}>${esc(v.note)}</textarea></label><p class="tiny muted">原状态：无此批注 → 新状态：高亮与以上笔记</p>`:`<p>页面方向：${v.before==='landscape'?'横向':'纵向'} → ${v.after==='landscape'?'横向':'纵向'}</p><p class="tiny muted">仅调整示例版式，不修改真实 PDF。</p>`}<div class="od-cluster">${btn('查看原文','agent-source','text','arrow',`data-document="${v.documentId}" data-page="${v.anchor.page_index+1}"`)}${pending?btn('拒绝','agent-reject','text danger','',`data-id="${v.id}"`):''}</div></article>`}
function evidenceCard(e){const d=docById(e.documentId);return `<article class="agent-evidence"><div class="od-row"><span class="tiny muted od-fill">${d.name} · 第 ${e.anchor.page_index+1} 页</span><span class="agent-label">原文</span></div><p>${esc(e.anchor.quote.exact)}</p><div class="od-cluster">${btn('核对原文','agent-source','text','arrow',`data-document="${d.id}" data-page="${e.anchor.page_index+1}"`)}${btn('复制引用','agent-copy','text','copy',`data-id="${e.id}"`)}${btn('建议页面横置','agent-layout-propose','text','rotate',`data-id="${e.id}"`)}</div><details><summary>位置与提取来源</summary><p class="tiny muted">文档版本 ${e.anchor.revision} · 第 ${e.anchor.page_index+1} 页 · 标准化页内坐标 ${e.anchor.rect.join(', ')}<br>来源：自编示例文本。未运行 PDF 解析或 OCR，未生成置信度。</p></details></article>`}
function agentView(){if(!A.task)return `<main class="reader-scroll"><div class="agent-intro"><section>${taskForm()}</section><aside class="agent-principles"><h2>每个动作，都有边界。</h2><div><h3>先授权，再读取</h3><p>指定文档与操作范围，随时撤销。</p></div><div><h3>证据留在原文里</h3><p>每条结果都携带文档版本、页码和原句。</p></div><div><h3>修改可以核对</h3><p>批注与页面修改先形成提案，应用后可以撤销。</p></div><div class="agent-connection"><span class="save-dot" style="background:${A.connected?'var(--success)':'var(--mute)'}"></span><span>${grantSummary()}</span></div></aside></div></main>`;
const t=A.task,pending=A.proposals.filter(p=>p.status==='pending'),chosen=pending.filter(p=>p.selected),running=t.status==='running';return `<main class="view"><header class="agent-taskbar"><div class="od-field od-fill"><span class="eyebrow">AGENT 任务 / 本地演示</span><h1>${esc(t.objective)}</h1><span class="tiny muted">${t.docs.length} 份文档 · 关键词：${esc(t.keywords)} · ${agentStatus()}</span></div><div class="od-cluster">${running?btn('停止','agent-stop','','close') :''}${running||t.status==='review'?btn('我来接管','agent-takeover','text'):''}${['failed','cancelled','paused'].includes(t.status)?btn(A.connected?'继续任务':'重新授权','agent-resume','primary','arrow'):''}${btn('新任务','agent-new','text','plus')}</div></header>${taskSteps()}${running?'<div class="progress" aria-label="任务执行中"></div>':''}${t.status==='failed'?`<div class="notice error"><p>${esc(t.error||'访问授权已失效')}。已找到的证据保留，恢复授权后可继续。</p>${btn('调整授权','agent-connect')}</div>`:''}${t.status==='paused'?'<div class="notice"><p>你已接管。自动执行暂停，现有证据与提案保留。</p></div>':''}${t.status==='cancelled'?'<div class="notice"><p>任务已停止，没有自动应用任何修改。可继续剩余步骤。</p></div>':''}<div class="workspace agent-review"><section class="view"><div class="agent-section-head od-row"><h2 class="od-fill">证据 <span class="muted">${A.evidence.length}</span></h2>${btn('导出任务记录','agent-export','text','download')}</div><div class="reader-scroll"><div class="agent-evidence-list">${A.evidence.length?A.evidence.map(evidenceCard).join(''):running?'<p class="muted">正在检查文档与提取示例证据…</p>':'<div class="empty"><h2>没有匹配证据</h2><p>当前结果为空，可创建新任务调整关键词与范围。</p>'+btn('修改任务','agent-new')+'</div>'}<details class="agent-audit"><summary>查看本次操作记录 · ${A.audit.filter(v=>v.detail.task===t.id).length} 条</summary><ol>${A.audit.filter(v=>v.detail.task===t.id).map(v=>`<li><time>${new Date(v.at).toLocaleTimeString('zh-CN')}</time> · ${esc(v.detail.message||v.action)}</li>`).join('')}</ol></details></div></div></section><aside class="inspector agent-proposal-panel"><div class="inspector-head"><h2>待核对修改 <span class="muted">${pending.length}</span></h2><span class="tiny muted">原文不会静默改变</span></div><div class="inspector-body">${A.proposals.length?A.proposals.map(proposalCard).join(''):'<p class="muted">找到证据后，Agent 会准备批注提案。</p>'}</div><div class="composer"><p class="tiny muted">${chosen.length} 项已选 · 应用前检查权限与文档版本</p><div class="od-cluster">${btn('核对并应用','agent-apply-preview','primary','check',!chosen.length||running?'disabled':'')}${btn('拒绝所选','agent-reject-selected','text danger','',!chosen.length||running?'disabled':'')}</div>${A.transactions.length?btn('撤销最近一次应用','agent-undo','','undo'):''}</div></aside></div>${status(grantSummary(),'<span>读取、修改和外发分别授权</span>')}</main>`}
function agentDocument(){const src=A.source,d=docById(src.documentId),block=d.blocks.find(b=>b.page===src.page),notes=A.annotations.filter(n=>n.documentId===d.id&&n.page===src.page),landscape=A.layouts[d.id+':'+src.page]==='landscape';return `<main class="view"><div class="docbar"><div class="od-field od-fill"><span class="docname">${d.name}</span><span class="docsub">PDF 版式示例 · 版本 ${d.revision} · 第 ${src.page} / ${d.pages} 页</span></div>${btn('返回 Agent 任务','agent-return','text','back')}${btn('显示批注 '+notes.length,'agent-doc-notes')}</div><div class="notice"><p class="tiny">定位到证据原句。此处为自编 PDF 版式示例，不是已解析的真实 PDF。</p></div><div class="reader-scroll"><div class="pdf-stage"><article class="pdf-sheet ${landscape?'landscape':''}"><div class="tiny muted">RESEARCH NOTES / ${d.id==='lab-a'?'A':'B'}</div><h2>${block.title}</h2><p>文档中的每一条证据，都应能回到可核对的原文位置。以下页面展示原句、上下文和批注之间的对应关系。</p><div class="agent-source-highlight"><span class="agent-label">Agent 定位 · 第 ${src.page} 页</span><p>${notes.length?'<mark>':''}${esc(block.text)}${notes.length?'</mark>':''}</p></div><h3>记录说明</h3><p>本页为 Booklight 自编演示内容。证据位置与页面布局共同编排，不表示已经实现真实 PDF 文本抽取或坐标识别。</p>${notes.map(n=>`<div class="agent-page-note"><span class="tiny muted">Agent 批注 · 已核对</span><p>${esc(n.note)}</p></div>`).join('')}<div class="folio"><span>${d.name} · 自编示例</span><span>${src.page}</span></div></article></div></div>${status('Agent 证据定位 · 原文与提案使用同一文档版本',btn('返回任务','agent-return','text','back'))}</main>`}
function saveAgentDraft(){if($('#agentObjective'))A.objective=$('#agentObjective').value.trim();if($('#agentKeywords'))A.keywords=$('#agentKeywords').value.trim();if($$('input[name="taskDoc"]').length)A.selectedDocs=$$('input[name="taskDoc"]:checked').map(x=>x.value)}
function stopAgent(status,message){clearTimeout(A.tick);A.epoch++;if(A.task){A.task.status=status;agentLog(status,{task:A.task.id,message})}render();announce(message)}
function runAgent(){const t=A.task,epoch=++A.epoch;t.status='running';t.error=null;render();const schedule=()=>{A.tick=setTimeout(()=>{if(epoch!==A.epoch||t.status!=='running')return;if(!A.connected||!A.grant.read||t.docs.some(id=>!canRead(id))){t.error='任务所需的读取授权已撤销或范围已改变';stopAgent('failed',t.error);return}if(t.phase===0){agentLog('scope.checked',{task:t.id,message:'已核对 '+t.docs.length+' 份文档的读取权限'});t.phase=1}else if(t.phase===1){const terms=t.keywords.toLowerCase().split(/\s+/).filter(Boolean);const id=t.docs[t.cursor];if(id){const d=docById(id);d.blocks.filter(b=>terms.some(term=>b.text.toLowerCase().includes(term))).forEach(b=>{if(!A.evidence.some(e=>e.documentId===id&&e.anchor.page_index===b.page-1))A.evidence.push({id:aid('evidence'),documentId:id,anchor:localAnchor(d,b)})});t.cursor++;agentLog('document.searched',{task:t.id,document_id:id,message:'已检索《'+d.name+'》，保留原句与页码'});if(t.cursor>=t.docs.length)t.phase=2}else if(t.phase===2){agentLog('evidence.resolved',{task:t.id,message:'已核对 '+A.evidence.length+' 条证据的文档版本与原句'});t.phase=3}else if(t.phase===3){A.evidence.forEach(e=>{if(!A.proposals.some(p=>p.evidenceId===e.id&&p.type==='annotation'))A.proposals.push({id:aid('proposal'),type:'annotation',documentId:e.documentId,baseRevision:revision(e.documentId),anchor:structuredClone(e.anchor),evidenceId:e.id,note:'待核对：这段原文说明了测量比较需要关注的条件。',selected:true,status:'pending'})});t.phase=4;t.status=A.evidence.length?'review':'no_results';agentLog('proposal.prepared',{task:t.id,message:A.evidence.length?'批注提案已准备，等待用户核对':'没有匹配证据，未生成修改提案'});render();announce(A.evidence.length?'证据与提案已准备，请核对原文':'没有匹配证据，请调整关键词');return}render();schedule()}},800)};schedule()}
function beginAgent(){saveAgentDraft();if(!A.objective||!A.keywords||!A.selectedDocs.length){const error=$('#agentFormError');if(error){error.hidden=false;error.textContent='请填写任务目标、检索关键词，并选择至少一份文档。'}return}if(A.selectedDocs.some(id=>!canRead(id))){A.startAfterGrant=true;grantDialog();return}A.evidence=[];A.proposals=[];A.transactions=[];A.task={id:aid('task'),objective:A.objective,keywords:A.keywords,docs:[...A.selectedDocs],status:'running',phase:0,cursor:0};agentLog('task.created',{task:A.task.id,message:'已创建本地任务，未发起外部调用'});runAgent()}
function proposalProblem(p){const d=docById(p.documentId);if(!d)return '文档不可用';if(d.revision!==p.baseRevision)return '文档版本已改变，请重新核对';const b=d.blocks.find(x=>x.page===p.anchor.page_index+1);if(!b||b.text!==p.anchor.quote.exact)return '原句已改变，无法可靠定位';return null}
function applyPreview(){const chosen=A.proposals.filter(p=>p.status==='pending'&&p.selected);if(!chosen.length)return;const bad=chosen.find(p=>proposalProblem(p));if(bad){showDialog('<h2>需要重新核对</h2><p>'+esc(proposalProblem(bad))+'。本次没有应用任何修改。</p><div class="dialog-actions">'+btn('取消','dialog-close')+btn('刷新提案版本','agent-refresh-proposals','primary')+'</div>');return}const docIds=[...new Set(chosen.map(p=>p.documentId))];const missing=chosen.filter(p=>!A.connected||!A.grant.docs.includes(p.documentId)||(p.type==='annotation'?!A.grant.annotate:!A.grant.edit));A.pendingApply={ids:chosen.map(p=>p.id),versions:Object.fromEntries(docIds.map(id=>[id,revision(id)])),grantVersion:A.grantVersion,oneTime:missing.length>0};showDialog(`<h2>核对这次修改</h2><p>${chosen.filter(p=>p.type==='annotation').length} 条批注 · ${chosen.filter(p=>p.type==='layout').length} 项页面布局修改，涉及 ${docIds.length} 份文档。</p><ul>${docIds.map(id=>`<li>${docById(id).name} · 版本 ${revision(id)}</li>`).join('')}</ul><p>${missing.length?'当前会话未授权全部写入能力。点击下方按钮，仅批准这次所列修改；不扩展后续任务权限。':'这些操作在当前授权范围内。应用后可以撤销。'}</p><p class="tiny muted">原始 PDF 不会修改；这次应用只写入原型会话中的批注与布局状态。不会外发。</p><div class="dialog-actions">${btn('返回核对','dialog-close')}${btn(missing.length?'仅批准并应用这一次':'应用已核对修改','agent-apply','primary')}</div>`)}
function applyProposals(){const packet=A.pendingApply;if(!packet)return;const chosen=packet.ids.map(id=>A.proposals.find(p=>p.id===id)).filter(Boolean);if(A.grantVersion!==packet.grantVersion||chosen.length!==packet.ids.length||chosen.some(p=>p.status!=='pending'||proposalProblem(p))){closeDialog();announce('授权或文档状态已变化，请重新核对');return}const tx={id:aid('transaction'),proposalIds:packet.ids,notes:[],layouts:[],docs:Object.keys(packet.versions),after:{}};chosen.forEach(v=>{if(v.type==='annotation'){const n={id:aid('annotation'),documentId:v.documentId,page:v.anchor.page_index+1,anchor:structuredClone(v.anchor),note:v.note,task:A.task.id};A.annotations.push(n);tx.notes.push(n.id)}else{const key=v.documentId+':'+(v.anchor.page_index+1);tx.layouts.push({key,before:A.layouts[key]||'portrait'});A.layouts[key]=v.after}v.status='applied';v.selected=false});tx.docs.forEach(id=>{docById(id).revision++;tx.after[id]=revision(id)});A.transactions.push(tx);agentLog('changes.applied',{task:A.task.id,transaction:tx.id,one_time:packet.oneTime,message:'用户核对后应用 '+chosen.length+' 项修改，可撤销'});A.pendingApply=null;if(!A.proposals.some(p=>p.status==='pending'))A.task.status='completed';closeDialog();render();announce('已应用所选修改，可在原文核对或撤销')}
function exportAgent(){download('booklight-agent-task.json',JSON.stringify({kind:'local-prototype-record-not-engine-output',task:A.task,evidence:A.evidence,proposals:A.proposals,annotations:A.annotations,layouts:A.layouts,audit:A.audit.filter(e=>e.detail.task===A.task?.id),limitations:['authored sample content','no MCP server','no PDF parser or OCR','no network calls']},null,2))}
Object.assign(actions,{
'agent-connect':()=>{saveAgentDraft();grantDialog()},
'agent-authorize':()=>{const docs=$$('input[name="agentDoc"]:checked').map(n=>n.value);const read=$('#grantRead').checked;if(!docs.length){$('#grantError').hidden=false;$('#grantError').textContent='请选择至少一份可访问文档。';return}A.grant={docs,read,annotate:$('#grantNote').checked,edit:$('#grantEdit').checked,external:false};A.connected=true;A.grantVersion++;agentLog('grant.updated',{task:A.task?.id,message:'用户更新了本次会话授权'});closeDialog();render();if(A.startAfterGrant){A.startAfterGrant=false;if(A.selectedDocs.every(canRead)){beginAgent()}else announce('任务文档尚未获得完整读取权限，请调整授权或任务范围')}else announce('本次会话授权已更新，未建立真实外部连接')},
'agent-revoke':()=>{A.connected=false;A.grantVersion++;A.startAfterGrant=false;A.pendingApply=null;if(A.task?.status==='running')stopAgent('failed','读取授权已撤销');else{agentLog('grant.revoked',{task:A.task?.id,message:'用户撤销全部会话权限'});render();announce('已撤销全部授权')}},
'agent-start':beginAgent,'agent-stop':()=>stopAgent('cancelled','任务已停止，证据与提案保留'),'agent-takeover':()=>stopAgent('paused','你已接管任务，Agent 不再自动推进'),
'agent-resume':()=>{if(!A.task)return;if(!A.task.docs.every(canRead)){grantDialog();return}if(A.task.phase>=4){A.task.status='review';render()}else runAgent()},
'agent-new':()=>{if(A.task?.status==='running'){showDialog('<h2>停止当前任务并创建新任务？</h2><p>当前任务可先导出记录。新任务会清空当前证据与未应用提案，已应用批注保留。</p><div class="dialog-actions">'+btn('取消','dialog-close')+btn('停止并新建','agent-new-confirm','primary')+'</div>')}else showDialog('<h2>创建新任务</h2><p>当前记录不会自动归档，可先导出。已应用的批注与布局保留。</p><div class="dialog-actions">'+btn('导出当前记录','agent-export')+btn('取消','dialog-close')+btn('创建新任务','agent-new-confirm','primary')+'</div>')},
'agent-new-confirm':()=>{clearTimeout(A.tick);A.epoch++;A.task=null;A.evidence=[];A.proposals=[];A.transactions=[];closeDialog();navigate('agent')},
'agent-source':b=>{A.source={documentId:b.dataset.document,page:+b.dataset.page};A.returnScreen='agent';navigate('pdf')},'agent-return':()=>{A.source=null;navigate('agent')},
'agent-doc-notes':()=>{const notes=A.annotations.filter(n=>n.documentId===A.source.documentId&&n.page===A.source.page);showDialog('<h2>此页批注 · '+notes.length+'</h2>'+(notes.length?notes.map(n=>'<p>'+esc(n.note)+'</p>').join(''):'<p>此页尚无已应用的 Agent 批注。</p>')+'<div class="dialog-actions">'+btn('返回原文','dialog-close')+'</div>')},
'agent-copy':b=>{const e=A.evidence.find(e=>e.id===b.dataset.id);copy('“'+e.anchor.quote.exact+'”\n——《'+docById(e.documentId).name+'》第 '+(e.anchor.page_index+1)+' 页 · 版本 '+e.anchor.revision+'（自编示例）')},
'agent-layout-propose':b=>{const e=A.evidence.find(e=>e.id===b.dataset.id);if(A.proposals.some(p=>p.type==='layout'&&p.documentId===e.documentId&&p.anchor.page_index===e.anchor.page_index&&p.status==='pending')){announce('该页已有待核对布局提案');return}const before=A.layouts[e.documentId+':'+(e.anchor.page_index+1)]||'portrait';A.proposals.push({id:aid('proposal'),type:'layout',documentId:e.documentId,baseRevision:revision(e.documentId),anchor:{...structuredClone(e.anchor),revision:revision(e.documentId)},before,after:before==='portrait'?'landscape':'portrait',selected:true,status:'pending'});if(A.task.status==='completed')A.task.status='review';agentLog('layout.proposed',{task:A.task.id,message:'用户要求准备页面方向提案'});render();announce('已添加页面方向提案，尚未应用')},
'agent-reject':b=>{const v=A.proposals.find(p=>p.id===b.dataset.id);if(v?.status==='pending'){v.status='rejected';v.selected=false;agentLog('proposal.rejected',{task:A.task.id,message:'用户拒绝一项提案'});if(!A.proposals.some(p=>p.status==='pending'))A.task.status='completed';render();$('.agent-proposal-panel h2')?.setAttribute('tabindex','-1');$('.agent-proposal-panel h2')?.focus()}},
'agent-reject-selected':()=>{A.proposals.filter(p=>p.status==='pending'&&p.selected).forEach(p=>{p.status='rejected';p.selected=false});agentLog('proposal.rejected',{task:A.task.id,message:'用户拒绝所选提案'});if(!A.proposals.some(p=>p.status==='pending'))A.task.status='completed';render()},
'agent-apply-preview':applyPreview,'agent-apply':applyProposals,
'agent-refresh-proposals':()=>{A.proposals.filter(p=>p.status==='pending').forEach(p=>{const d=docById(p.documentId),b=d.blocks.find(b=>b.page===p.anchor.page_index+1);if(b&&b.text===p.anchor.quote.exact){p.baseRevision=d.revision;p.anchor=localAnchor(d,b);if(p.type==='layout'){p.before=A.layouts[d.id+':'+b.page]||'portrait';p.after=p.before==='portrait'?'landscape':'portrait'}}});closeDialog();render();announce('已刷新可定位提案，请重新核对再应用')},
'agent-undo':()=>{const tx=A.transactions[A.transactions.length-1];if(!tx)return;if(tx.docs.some(id=>revision(id)!==tx.after[id])){announce('文档已被后续操作改变，不能直接撤销');return}showDialog('<h2>撤销最近一次应用？</h2><p>移除该次批注并恢复页面布局，不影响其他操作。</p><div class="dialog-actions">'+btn('取消','dialog-close')+btn('撤销这次应用','agent-undo-confirm','primary')+'</div>')},
'agent-undo-confirm':()=>{const tx=A.transactions[A.transactions.length-1];if(!tx||tx.docs.some(id=>revision(id)!==tx.after[id])){closeDialog();announce('文档版本已变化，未执行撤销');return}A.annotations=A.annotations.filter(n=>!tx.notes.includes(n.id));tx.layouts.forEach(x=>A.layouts[x.key]=x.before);tx.docs.forEach(id=>docById(id).revision++);tx.proposalIds.forEach(id=>{const v=A.proposals.find(p=>p.id===id);if(v)v.status='undone'});A.transactions.pop();if(A.transactions.length){const previous=A.transactions[A.transactions.length-1];previous.docs.forEach(id=>{if(tx.docs.includes(id))previous.after[id]=revision(id)})}agentLog('changes.undone',{task:A.task?.id,message:'用户撤销最近一次应用'});closeDialog();render();announce('已撤销；文档版本已更新')},'agent-export':exportAgent
});
document.addEventListener('input',e=>{const t=e.target;if(t.dataset.proposalNote){const v=A.proposals.find(p=>p.id===t.dataset.proposalNote);if(v?.status==='pending')v.note=t.value}if(t.id==='agentObjective')A.objective=t.value;if(t.id==='agentKeywords')A.keywords=t.value});
document.addEventListener('change',e=>{const t=e.target;if(t.dataset.proposal){const v=A.proposals.find(p=>p.id===t.dataset.proposal);if(v?.status==='pending'){v.selected=t.checked;const scroll=$('.agent-proposal-panel .inspector-body')?.scrollTop||0;render();const panel=$('.agent-proposal-panel .inspector-body');if(panel)panel.scrollTop=scroll;$(`[data-proposal="${v.id}"]`)?.focus()}}if(t.name==='taskDoc')A.selectedDocs=$$('input[name="taskDoc"]:checked').map(n=>n.value)});

render();
})();

function refreshPrototypeTheme(){S.theme=preferredTheme();applyTheme();syncThemeToggle();const select=document.getElementById('appTheme');if(select)select.value=S.theme;}
window.addEventListener('storage',e=>{if(e.key===THEME_KEY||e.key===null)refreshPrototypeTheme()});
themeMedia.addEventListener('change',refreshPrototypeTheme);
